<script setup lang="ts">
import { onMounted, onUnmounted, ref } from 'vue';
const labels=ref<any[]>([]), selected=ref(''), result=ref<any>({items:[],total:0}), view=ref('documents');
const query=ref(''), keyword=ref(''), offset=ref(0), name=ref(''), description=ref(''), editing=ref(false), busy=ref(false), error=ref(''), selectedHit=ref<any>();
const status=ref<any>({pendingResources:0,failed:0}), search=ref(''), totalLabels=ref(0), labelOffset=ref(0);
const PAGE=30; // 浏览分页与后台处理批次独立。
let timer:ReturnType<typeof setInterval>|undefined;let requestVersion=0;let disposed=false;let refreshing=false;
const stateName=(state:string)=>({queued:'等待匹配',processing:'正在匹配',ready:'已更新',failed:'匹配失败'}[state]??'等待匹配');
async function api(path:string,method='GET',body?:unknown){const response=await fetch('/api/semantic/'+path,{method,...(body===undefined?{}:{headers:{'Content-Type':'application/json'},body:JSON.stringify(body)})});const json=await response.json();if(!response.ok||!json.ok)throw new Error(json.error?.message??'操作失败');return json.data;}
function saveRoute(){const p=new URLSearchParams(location.hash.split('?')[1]);p.set('type','tag');p.delete('id');if(selected.value)p.set('id',selected.value);p.set('semanticView',view.value);history.replaceState(null,'','#browse?'+p);}
async function loadResults(){const generation=++requestVersion;if(!selected.value){result.value={items:[],total:0};return;}const params=new URLSearchParams({view:view.value,query:query.value,keyword:keyword.value,offset:String(offset.value),limit:String(PAGE)});const value=await api('tags/'+selected.value+'?'+params);if(generation===requestVersion&&!disposed){result.value=value;if(selectedHit.value&&!value.items.some((item:any)=>(item.preview??item).id===selectedHit.value.id))selectedHit.value=undefined;}}
async function refresh(){if(refreshing)return;refreshing=true;try{const data=await api('tags?'+new URLSearchParams({query:search.value,offset:String(labelOffset.value),limit:String(PAGE)}));if(disposed)return;labels.value=data.items;totalLabels.value=data.total;status.value=data.status;await loadResults();error.value='';}catch(e){if(!disposed)error.value=(e as Error).message;}finally{refreshing=false;}}
async function choose(id:string){selected.value=id;offset.value=0;keyword.value='';selectedHit.value=undefined;saveRoute();try{await loadResults();}catch(e){error.value=(e as Error).message;}}
async function switchView(value:string){view.value=value;offset.value=0;selectedHit.value=undefined;saveRoute();await loadResults();}
async function submit(){busy.value=true;try{const tag=await api('tags','POST',{name:name.value,description:description.value});name.value='';description.value='';editing.value=false;await choose(tag.id);await refresh();}catch(e){error.value=(e as Error).message;}finally{busy.value=false;}}
async function remove(tag:any){if(!confirm(`删除标签“${tag.name}”？文档、片元和关键词会保留。`))return;busy.value=true;try{await api('tags/'+tag.id,'DELETE');if(selected.value===tag.id){selected.value='';selectedHit.value=undefined;result.value={items:[],total:0};saveRoute();}await refresh();}catch(e){error.value=(e as Error).message;}finally{busy.value=false;}}
async function retry(){busy.value=true;try{await api(selected.value?'tags/'+selected.value+'/retry':'retry','POST',{});await refresh();}catch(e){error.value=(e as Error).message;}finally{busy.value=false;}}
async function filterWord(value:string){keyword.value=value;view.value='fragments';offset.value=0;await loadResults();}
function route(){const p=new URLSearchParams(location.hash.split('?')[1]);selected.value=p.get('id')??'';const mode=p.get('semanticView');view.value=mode&&['documents','keywords','fragments'].includes(mode)?mode:'documents';void refresh();}
onMounted(()=>{route();window.addEventListener('hashchange',route);timer=setInterval(refresh,3000);});
onUnmounted(()=>{disposed=true;requestVersion++;if(timer)clearInterval(timer);window.removeEventListener('hashchange',route);});
</script>
<template>
  <section class="semantic-browser" aria-label="语义标签">
    <div class="semantic-toolbar"><div><h2>标签</h2><p>用概念查找相关内容，自动匹配文档与片元。</p></div><button class="primary" @click="editing=!editing">新增标签</button></div>
    <p v-if="error" class="error" role="alert">{{error}}</p>
    <form v-if="editing" class="semantic-create" @submit.prevent="submit"><label>标签名称<input v-model="name" required maxlength="100" placeholder="例如：性能优化"></label><label>含义说明（可选）<textarea v-model="description" maxlength="1000" placeholder="帮助区分概念或实体的含义"></textarea></label><div><button class="primary" :disabled="busy">保存并开始匹配</button><button type="button" @click="editing=false">取消</button></div></form>
    <div v-if="status.pendingResources||status.failed" class="semantic-notice" role="status"><span>{{status.pendingResources}} 篇内容待处理。{{status.error}}</span><button :disabled="busy" @click="retry">重试处理</button></div>
    <div class="semantic-layout">
      <aside class="semantic-labels"><form @submit.prevent="labelOffset=0;refresh()"><input v-model="search" aria-label="搜索标签" placeholder="搜索标签"><button>搜索</button></form><p v-if="!labels.length">暂无标签，可以先新增一个概念。</p>
        <article v-for="tag in labels" :key="tag.id" :class="{active:selected===tag.id}"><button class="semantic-label" :aria-pressed="selected===tag.id" @click="choose(tag.id)"><strong>{{tag.name}}</strong><small>{{tag.count}} 篇 · {{stateName(tag.state)}}{{tag.partial?' · 部分内容待更新':''}}</small><small v-if="tag.description">{{tag.description}}</small></button><button class="semantic-delete" :aria-label="`删除标签 ${tag.name}`" :disabled="busy" @click="remove(tag)">删除</button></article>
        <div class="pagination"><button :disabled="labelOffset===0" @click="labelOffset-=PAGE;refresh()">上一页</button><span>{{totalLabels}} 个</span><button :disabled="labelOffset+PAGE>=totalLabels" @click="labelOffset+=PAGE;refresh()">下一页</button></div>
      </aside>
      <section class="semantic-results">
        <p v-if="!selected" class="semantic-empty">选择一个标签，浏览相关关键词、文档和片元。</p>
        <template v-else><div class="semantic-toolbar"><div><h3>{{result.tag?.name}}</h3><small>{{stateName(result.tag?.state)}} · {{result.tag?.done??0}} / {{result.tag?.total??0}} 片元</small></div><button :disabled="busy" @click="retry">重新匹配</button></div>
          <p v-if="result.tag?.error" class="error">{{result.tag.error}}</p><p v-if="result.tag?.partial" class="semantic-notice">当前展示已完成的结果，其余内容仍在处理中。</p>
          <nav class="semantic-views" aria-label="标签结果类型"><button v-for="item in [{id:'keywords',name:'关键词'},{id:'documents',name:'文档'},{id:'fragments',name:'片元'}]" :key="item.id" :class="{active:view===item.id}" :aria-pressed="view===item.id" @click="switchView(item.id)">{{item.name}}</button></nav>
          <form class="semantic-search" @submit.prevent="offset=0;loadResults()"><input v-model="query" aria-label="筛选标签内容" placeholder="筛选标题或原文"><button>筛选</button><button v-if="keyword" type="button" @click="keyword='';offset=0;loadResults()">清除关键词：{{keyword}}</button></form>
          <p v-if="!result.items.length" class="semantic-empty">{{result.tag?.partial?'匹配尚未完成，请稍后查看。':'暂无匹配内容。'}}</p>
          <div v-if="view==='keywords'" class="semantic-words"><button v-for="item in result.items" :key="item.value" @click="filterWord(item.value)">{{item.value}} <small>{{item.documents}} 篇</small></button></div>
          <button v-else v-for="item in result.items" :key="item.id??item.resourceId" class="semantic-hit" @click="selectedHit=item.preview??item"><strong>{{item.title}}</strong><small>{{view==='documents'?`${item.fragments} 个命中片元`:`第 ${item.startLine}–${item.endLine} 行`}} · 相关度 {{item.score.toFixed(3)}}</small><p>{{(item.preview?.text??item.text).slice(0,220)}}</p></button>
          <div class="pagination"><button :disabled="offset===0" @click="offset-=PAGE;loadResults()">上一页</button><span>{{result.total}} 项</span><button :disabled="offset+PAGE>=result.total" @click="offset+=PAGE;loadResults()">下一页</button></div>
        </template>
      </section>
      <section v-if="selectedHit" class="semantic-original"><div class="semantic-toolbar"><h3>{{selectedHit.title}}</h3><button @click="selectedHit=undefined">关闭原文</button></div><p>原文 v{{selectedHit.contentVersion}} · 第 {{selectedHit.startLine}}–{{selectedHit.endLine}} 行</p><p v-if="selectedHit.truncated" class="semantic-notice">匹配使用了片元的部分内容，下方展示完整片元。</p><pre>{{selectedHit.text}}</pre><div class="semantic-words"><span v-for="word in selectedHit.keywords" :key="word.start+':'+word.value">{{word.value}}</span></div></section>
    </div>
  </section>
</template>
<style scoped>
.semantic-toolbar{display:flex;align-items:center;justify-content:space-between;gap:16px;margin:12px 0}.semantic-toolbar h2,.semantic-toolbar h3{margin:0}.semantic-toolbar p,.semantic-toolbar small{color:#61776a;margin:8px 0}.semantic-layout{display:grid;grid-template-columns:minmax(210px,.7fr) minmax(300px,1.5fr);gap:18px}.semantic-labels,.semantic-results,.semantic-original,.semantic-create{background:#fff;border:1px solid #dfe7df;border-radius:10px;padding:18px;min-width:0}.semantic-labels article{display:flex;border:1px solid #e5ebe3;border-radius:7px;margin:10px 0}.semantic-labels article.active,.semantic-views button.active{background:#edf3e9;border-color:#76936a}.semantic-label{display:flex;flex:1;flex-direction:column;gap:8px;text-align:left;min-width:0;background:none;border:0;overflow-wrap:anywhere}.semantic-label small{color:#61776a}.semantic-delete{align-self:center;margin-right:6px;background:none;color:#81534a}.semantic-create{display:grid;gap:14px;margin:16px 0;max-width:700px}.semantic-create label{display:grid;gap:8px}.semantic-create input,.semantic-create textarea,.semantic-search input,.semantic-labels input{padding:10px;border:1px solid #cbd8c7;border-radius:5px;min-width:0;max-width:100%;font:inherit}.semantic-create textarea{min-height:76px}.semantic-create button{margin-right:10px}.semantic-labels form,.semantic-search,.semantic-views{display:flex;gap:8px;flex-wrap:wrap;margin-bottom:14px}.semantic-search input,.semantic-labels input{flex:1}.semantic-notice{padding:12px;background:#f5f3e8;border-radius:6px;overflow-wrap:anywhere}.semantic-notice button{margin-left:10px}.semantic-words{display:flex;gap:10px;flex-wrap:wrap}.semantic-words span,.semantic-words button{padding:8px 12px;border-radius:6px;background:#edf3e9;overflow-wrap:anywhere}.semantic-hit{display:block;width:100%;text-align:left;border:1px solid #dfe7df;border-radius:7px;margin:10px 0;padding:16px;background:white;overflow-wrap:anywhere}.semantic-hit small{display:block;color:#61776a;margin:8px 0}.semantic-hit p{font-size:13px;margin:8px 0;line-height:1.7}.semantic-empty{padding:35px 10px;color:#61776a}.semantic-original{grid-column:1/-1}.semantic-original pre{white-space:pre-wrap;overflow-wrap:anywhere;line-height:1.8;font:inherit}.pagination{display:flex;align-items:center;gap:12px;margin-top:16px}@media(max-width:720px){.semantic-layout{grid-template-columns:1fr}.semantic-toolbar{align-items:flex-start}.semantic-labels,.semantic-results,.semantic-original{padding:12px}}
</style>
